    12	public class Main {
    13	    private static final Logger logger = LoggerFactory.getLogger(Main.class);
    14	
    15	    public static void main(String[] args) {
    16	        try {
    17	            Database.init();
    18	
    19	            int port = getPort();
    20	            Javalin app = Javalin.create().start(port);
    21	
    22	            RoomRoutes.register(app);
    23	            ReservationRoutes.register(app);
    24	            MessageRoutes.register(app);
    25	            ReportRoutes.register(app);
    26	
    27	            app.exception(Exception.class, (e, ctx) -> {
    28	                logger.error("Unexpected error", e);
    29	                ctx.status(500);
    30	                ctx.json(new ErrorResponse("INTERNAL_ERROR", "Internal server error"));
    31	            });
    32	
    33	            logger.info("Server started on port {}", port);
