    18	        app.get("/reports/occupancy", ctx -> {
    19	            try {
    20	                String dateStr = ctx.queryParam("date");
    21	                if (dateStr == null || dateStr.isEmpty()) {
    22	                    ctx.status(400);
    23	                    ctx.json(new ErrorResponse("INVALID_REQUEST", "date parameter is required"));
    24	                    return;
    25	                }
    26	
    27	                LocalDate date = LocalDate.parse(dateStr);
    28	                String csv = reportService.generateOccupancyReport(date);
    29	
    30	                ctx.contentType("text/csv; charset=utf-8");
    31	                ctx.result(csv);
    32	            } catch (Exception e) {
    33	                ctx.status(400);
    34	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid date format"));
    35	            }
    36	        });
    37	
    38	        app.get("/reports/revenue", ctx -> {
    39	            try {
    40	                String monthStr = ctx.queryParam("month");
    41	                if (monthStr == null || monthStr.isEmpty()) {
    42	                    ctx.status(400);
    43	                    ctx.json(new ErrorResponse("INVALID_REQUEST", "month parameter is required"));
    44	                    return;
    45	                }
    46	
    47	                YearMonth yearMonth = YearMonth.parse(monthStr);
    48	                String csv = reportService.generateRevenueReport(yearMonth.getYear(), yearMonth.getMonthValue());
    49	
    50	                ctx.contentType("text/csv; charset=utf-8");
    51	                ctx.result(csv);
    52	            } catch (Exception e) {
    53	                ctx.status(400);
    54	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid month format (expected yyyy-MM)"));
    55	            }
    56	        });
    57	    }
    58	}
