     8	import com.pousadamarealta.repository.ReservationRepository;
     9	import com.pousadamarealta.repository.RoomRepository;
    10	import com.pousadamarealta.repository.MessageRepository;
    11	import com.pousadamarealta.service.ReservationService;
    12	import com.pousadamarealta.utils.FormatterUtils;
    13	import com.pousadamarealta.ErrorResponse;
    14	
    15	import java.time.LocalDate;
    16	
    17	public class ReservationRoutes {
    18	    private static final ObjectMapper mapper = new ObjectMapper();
    19	
    20	    public static void register(Javalin app) throws Exception {
    21	        ReservationRepository reservationRepository = new ReservationRepository();
    22	        RoomRepository roomRepository = new RoomRepository();
    23	        MessageRepository messageRepository = new MessageRepository();
    24	        ReservationService reservationService = new ReservationService(
    25	            reservationRepository,
    26	            roomRepository,
    27	            messageRepository
    28	        );
    29	
    30	        app.post("/reservations", ctx -> {
    31	            try {
    32	                JsonNode body = mapper.readTree(ctx.body());
    33	
    34	                int roomNumber = body.get("roomNumber").asInt();
    35	                String guestName = body.get("guestName").asText();
    36	                String guestEmail = body.get("guestEmail").asText();
    37	                String guestCpf = body.get("guestCpf").asText();
    38	                LocalDate checkIn = LocalDate.parse(body.get("checkIn").asText());
    39	                LocalDate checkOut = LocalDate.parse(body.get("checkOut").asText());
    40	                int guests = body.get("guests").asInt();
    41	                RatePlan ratePlan = RatePlan.valueOf(body.get("ratePlan").asText());
    42	
    43	                var reservation = reservationService.createReservation(
    44	                    roomNumber, guestName, guestEmail, guestCpf,
    45	                    checkIn, checkOut, guests, ratePlan
    46	                );
    47	
    48	                ctx.status(201);
    49	                ctx.json(reservation);
    50	            } catch (Exception e) {
    51	                handleError(ctx, e);
    52	            }
    53	        });
    54	
    55	        app.get("/reservations/:id", ctx -> {
    56	            try {
    57	                long id = Long.parseLong(ctx.pathParam("id"));
    58	                var reservation = reservationService.getReservation(id)
    59	                    .orElseThrow(() -> new Exception("RESERVATION_NOT_FOUND"));
    60	                ctx.json(reservation);
    61	            } catch (Exception e) {
    62	                handleError(ctx, e);
    63	            }
    64	        });
    65	
    66	        app.post("/reservations/:id/confirmation", ctx -> {
    67	            try {
    68	                long id = Long.parseLong(ctx.pathParam("id"));
    69	                var reservation = reservationService.confirmReservation(id);
    70	                ctx.json(reservation);
    71	            } catch (Exception e) {
    72	                handleError(ctx, e);
    73	            }
    74	        });
    75	
    76	        app.post("/reservations/:id/check-in", ctx -> {
    77	            try {
    78	                long id = Long.parseLong(ctx.pathParam("id"));
    79	                var reservation = reservationService.checkIn(id);
    80	                ctx.json(reservation);
    81	            } catch (Exception e) {
    82	                handleError(ctx, e);
    83	            }
    84	        });
    85	
    86	        app.post("/reservations/:id/check-out", ctx -> {
    87	            try {
    88	                long id = Long.parseLong(ctx.pathParam("id"));
    89	                var reservation = reservationService.checkOut(id);
    90	
    91	                ReceiptResponse receipt = new ReceiptResponse(
    92	                    reservation.id,
    93	                    reservation.guestName,
    94	                    reservation.guestCpf,
    95	                    reservation.roomNumber,
    96	                    reservation.roomType,
    97	                    reservation.checkIn,
    98	                    reservation.checkOut,
    99	                    reservation.nights,
   100	                    reservation.subtotal,
   101	                    reservation.discount,
   102	                    reservation.total
   103	                );
   104	
   105	                ctx.json(receipt);
   106	            } catch (Exception e) {
   107	                handleError(ctx, e);
   108	            }
   109	        });
   110	
   111	        app.get("/reservations/:id/document", ctx -> {
   112	            try {
   113	                long id = Long.parseLong(ctx.pathParam("id"));
   114	                var reservation = reservationService.getReservation(id)
   115	                    .orElseThrow(() -> new Exception("RESERVATION_NOT_FOUND"));
   116	
   117	                ReceiptResponse receipt = new ReceiptResponse(
   118	                    reservation.id,
   119	                    reservation.guestName,
   120	                    reservation.guestCpf,
   121	                    reservation.roomNumber,
   122	                    reservation.roomType,
   123	                    reservation.checkIn,
   124	                    reservation.checkOut,
   125	                    reservation.nights,
   126	                    reservation.subtotal,
   127	                    reservation.discount,
   128	                    reservation.total
   129	                );
   130	
   131	                ctx.json(receipt);
   132	            } catch (Exception e) {
   133	                handleError(ctx, e);
   134	            }
   135	        });
   136	
   137	        app.post("/reservations/:id/cancellation", ctx -> {
   138	            try {
   139	                long id = Long.parseLong(ctx.pathParam("id"));
   140	                var reservation = reservationService.cancelReservation(id);
   141	                ctx.json(reservation);
   142	            } catch (Exception e) {
   143	                handleError(ctx, e);
   144	            }
   145	        });
   146	    }
   147	
   148	    private static void handleError(io.javalin.http.Context ctx, Exception e) {
   149	        String message = e.getMessage();
   150	
   151	        if (message.equals("ROOM_NOT_FOUND")) {
   152	            ctx.status(404);
   153	            ctx.json(new ErrorResponse("ROOM_NOT_FOUND", "Room not found"));
   154	        } else if (message.equals("RESERVATION_NOT_FOUND")) {
   155	            ctx.status(404);
   156	            ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reservation not found"));
   157	        } else if (message.equals("ROOM_UNAVAILABLE")) {
   158	            ctx.status(409);
   159	            ctx.json(new ErrorResponse("ROOM_UNAVAILABLE", "Room is not available for the requested dates"));
   160	        } else if (message.equals("CAPACITY_EXCEEDED")) {
   161	            ctx.status(422);
   162	            ctx.json(new ErrorResponse("CAPACITY_EXCEEDED", "Number of guests exceeds room capacity"));
   163	        } else if (message.equals("OPERATION_NOT_ALLOWED")) {
   164	            ctx.status(409);
   165	            ctx.json(new ErrorResponse("OPERATION_NOT_ALLOWED", "Operation not allowed for this reservation status"));
   166	        } else if (message.equals("INVALID_REQUEST")) {
   167	            ctx.status(400);
   168	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Invalid request data"));
   169	        } else {
   170	            ctx.status(500);
   171	            ctx.json(new ErrorResponse("INTERNAL_ERROR", "Internal server error"));
   172	        }
   173	    }
   174	}
