    65	        reservation.roomNumber = roomNumber;
    66	        reservation.roomType = room.type;
    67	        reservation.guestName = guestName;
    68	        reservation.guestEmail = guestEmail;
    69	        reservation.guestCpf = guestCpf;
    70	        reservation.checkIn = checkIn;
    71	        reservation.checkOut = checkOut;
    72	        reservation.guests = guests;
    73	        reservation.ratePlan = ratePlan;
    74	        reservation.nights = nights;
    75	        reservation.subtotal = subtotal;
    76	        reservation.discount = discount;
    77	        reservation.total = total;
    78	        reservation.status = ReservationStatus.PENDING;
    79	        reservation.amountPaid = BigDecimal.ZERO;
    80	
    81	        return reservationRepository.create(reservation);
    82	    }
    83	
    84	    public Reservation confirmReservation(long id) throws Exception {
    85	        Reservation reservation = reservationRepository.findById(id)
    86	            .orElseThrow(() -> new Exception("RESERVATION_NOT_FOUND"));
    87	
    88	        if (reservation.status != ReservationStatus.PENDING) {
    89	            throw new Exception("OPERATION_NOT_ALLOWED");
    90	        }
    91	
    92	        reservation.status = ReservationStatus.CONFIRMED;
    93	        reservation.amountPaid = reservation.total;
    94	
    95	        reservationRepository.update(reservation);
    96	        notificationService.notifyConfirmation(reservation);
    97	
    98	        return reservation;
    99	    }
   100	
   101	    public Reservation checkIn(long id) throws Exception {
   102	        Reservation reservation = reservationRepository.findById(id)
   103	            .orElseThrow(() -> new Exception("RESERVATION_NOT_FOUND"));
   104	
   105	        if (reservation.status != ReservationStatus.CONFIRMED) {
   106	            throw new Exception("OPERATION_NOT_ALLOWED");
   107	        }
   108	
   109	        reservation.status = ReservationStatus.CHECKED_IN;
   110	        reservationRepository.update(reservation);
   111	
   112	        return reservation;
   113	    }
   114	
   115	    public Reservation checkOut(long id) throws Exception {
   116	        Reservation reservation = reservationRepository.findById(id)
   117	            .orElseThrow(() -> new Exception("RESERVATION_NOT_FOUND"));
   118	
   119	        if (reservation.status != ReservationStatus.CHECKED_IN) {
   120	            throw new Exception("OPERATION_NOT_ALLOWED");
   121	        }
   122	
   123	        reservation.status = ReservationStatus.CHECKED_OUT;
   124	        reservationRepository.update(reservation);
   125	
   126	        return reservation;
   127	    }
   128	
   129	    public Reservation cancelReservation(long id) throws Exception {
   130	        Reservation reservation = reservationRepository.findById(id)
   131	            .orElseThrow(() -> new Exception("RESERVATION_NOT_FOUND"));
   132	
   133	        if (reservation.status != ReservationStatus.PENDING &&
   134	            reservation.status != ReservationStatus.CONFIRMED) {
   135	            throw new Exception("OPERATION_NOT_ALLOWED");
   136	        }
   137	
   138	        boolean wasConfirmed = reservation.status == ReservationStatus.CONFIRMED;
   139	
   140	        if (wasConfirmed) {
   141	            if (reservation.ratePlan == RatePlan.STANDARD) {
   142	                reservation.refund = reservation.amountPaid;
   143	            } else {
   144	                reservation.refund = BigDecimal.ZERO;
   145	            }
   146	        } else {
   147	            reservation.refund = BigDecimal.ZERO;
   148	        }
   149	
   150	        reservation.status = ReservationStatus.CANCELLED;
   151	        reservationRepository.update(reservation);
   152	
   153	        if (wasConfirmed) {
   154	            notificationService.notifyCancellation(reservation);
   155	        }
   156	
   157	        return reservation;
   158	    }
   159	
   160	    public Optional<Reservation> getReservation(long id) throws Exception {
   161	        return reservationRepository.findById(id);
   162	    }
   163	
   164	    private void validateReservationInput(
   165	        int roomNumber,
   166	        LocalDate checkIn,
   167	        LocalDate checkOut,
   168	        int guests
   169	    ) throws Exception {
   170	        if (guests < 1) {
   171	            throw new Exception("INVALID_REQUEST");
   172	        }
   173	
   174	        if (checkOut.compareTo(checkIn) <= 0) {
   175	            throw new Exception("INVALID_REQUEST");
   176	        }
   177	    }
   178	
   179	    public NotificationService getNotificationService() {
   180	        return notificationService;
   181	    }
   182	}
