    18	    public Reservation create(Reservation res) throws Exception {
    19	        String sql = "INSERT INTO reservations " +
    20	            "(room_number, room_type, guest_name, guest_email, guest_cpf, check_in, check_out, guests, " +
    21	            "rate_plan, nights, subtotal, discount, total, status, amount_paid) " +
    22	            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) " +
