    87	            "WHERE room_number = ? " +
    88	            "AND status != 'CANCELLED' " +
    89	            "AND check_in < ? " +
    90	            "AND check_out > ?";
    91	
    92	        List<Reservation> reservations = new ArrayList<>();
    93	        try (Connection conn = Database.getConnection();
