   108	        String sql = "SELECT * FROM reservations " +
   109	            "WHERE status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT') " +
   110	            "AND check_in <= ? " +
   111	            "AND check_out > ? " +
   112	            "ORDER BY room_number";
   113	
   114	        List<Reservation> reservations = new ArrayList<>();
   115	        try (Connection conn = Database.getConnection();
   116	             PreparedStatement ps = conn.prepareStatement(sql)) {
   117	            ps.setObject(1, date);
   118	            ps.setObject(2, date);
