   131	            "AND EXTRACT(YEAR FROM check_in) = ? " +
   132	            "AND EXTRACT(MONTH FROM check_in) = ? " +
   133	            "AND (amount_paid > 0 OR refund > 0) " +
   134	            "ORDER BY check_in, id";
   135	
   136	        List<Reservation> reservations = new ArrayList<>();
   137	        try (Connection conn = Database.getConnection();
   138	             PreparedStatement ps = conn.prepareStatement(sql)) {
