   140	            ps.setInt(2, month);
   141	            try (ResultSet rs = ps.executeQuery()) {
   142	                while (rs.next()) {
   143	                    reservations.add(mapToReservation(rs));
   144	                }
   145	            }
   146	        }
   147	        return reservations;
   148	    }
