    52	            .append(" (CPF ").append(formatCpf(res.guestCpf)).append(")\n");
    53	        sb.append("Quarto: ").append(res.roomNumber).append("\n");
    54	        sb.append("Entrada: ").append(formatDate(res.checkIn))
    55	            .append(" | Saída: ").append(formatDate(res.checkOut))
    56	            .append(" | ").append(res.nights).append(" diária").append(res.nights != 1 ? "s" : "").append("\n");
