     1	package com.pousadamarealta.utils;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	
     7	public class PricingUtils {
     8	    private static final BigDecimal SEASON_MULTIPLIER = new BigDecimal("1.20");
     9	    private static final BigDecimal DISCOUNT_RATE = new BigDecimal("0.15");
    10	
    11	    public static boolean isHighSeason(LocalDate date) {
    12	        int month = date.getMonthValue();
    13	        int day = date.getDayOfMonth();
    14	
    15	        if (month == 7) return true;
    16	        if (month == 12 && day >= 15) return true;
    17	        if (month >= 1 && month <= 2) return true;
    18	
    19	        return false;
    20	    }
    21	
    22	    public static BigDecimal calculateNightPrice(BigDecimal nightlyRate, LocalDate date) {
    23	        if (isHighSeason(date)) {
    24	            return roundPrice(nightlyRate.multiply(SEASON_MULTIPLIER));
    25	        }
    26	        return nightlyRate;
    27	    }
    28	
    29	    public static BigDecimal roundPrice(BigDecimal value) {
    30	        return value.setScale(2, RoundingMode.HALF_EVEN);
    31	    }
    32	
    33	    public static int calculateNights(LocalDate checkIn, LocalDate checkOut) {
    34	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    35	    }
    36	
    37	    public static BigDecimal calculateSubtotal(
    38	        BigDecimal nightlyRate,
    39	        LocalDate checkIn,
    40	        LocalDate checkOut
    41	    ) {
    42	        int nights = calculateNights(checkIn, checkOut);
    43	        BigDecimal subtotal = BigDecimal.ZERO;
    44	
    45	        for (int i = 0; i < nights; i++) {
    46	            LocalDate date = checkIn.plusDays(i);
    47	            BigDecimal nightPrice = calculateNightPrice(nightlyRate, date);
    48	            subtotal = subtotal.add(nightPrice);
    49	        }
    50	
    51	        return roundPrice(subtotal);
    52	    }
    53	
    54	    public static BigDecimal calculateDiscount(BigDecimal subtotal, boolean isNonRefundable) {
    55	        if (isNonRefundable) {
    56	            return roundPrice(subtotal.multiply(DISCOUNT_RATE));
    57	        }
    58	        return BigDecimal.ZERO;
    59	    }
    60	
    61	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    62	        return roundPrice(subtotal.subtract(discount));
    63	    }
    64	}
